function decodeGeoTable(raw){
  var table = {};
  raw.split(";").forEach(function(entry){
    var parts = entry.split(",");
    if(parts.length === 3) table[parts[0]] = { lat: parseFloat(parts[1]), lng: parseFloat(parts[2]) };
  });
  return table;
}
